  const netUpperOk = netUpperResidual >= -tolerance;
  const grossOk = grossResidual >= -tolerance;
  return {
    exposures: measures,
    netLower: { bound: lower, residual: netLowerResidual, satisfied: netLowerOk },
    netUpper: { bound: upper, residual: netUpperResidual, satisfied: netUpperOk },
    grossCap: { bound: cap, residual: grossResidual, satisfied: grossOk },
    minimumFeasibleGross,
    boundsCompatible: cap >= minimumFeasibleGross - tolerance,
    feasible: netLowerOk && netUpperOk && grossOk,
  };
